(function () {
  "use strict";

  function trigger(elt, name, detail) {
    elt.dispatchEvent(new CustomEvent(name, { bubbles: true, detail: detail || {} }));
  }

  function methodOf(elt) {
    for (const method of ["get", "post", "patch", "delete"]) {
      const url = elt.getAttribute("hx-" + method);
      if (url) return { method: method.toUpperCase(), url };
    }
    return null;
  }

  function targetFor(elt, explicit) {
    const selector = explicit || elt.getAttribute("hx-target");
    if (!selector) return elt;
    if (selector === "body") return document.body;
    if (selector.startsWith("closest ")) return elt.closest(selector.slice(8).trim());
    return document.querySelector(selector);
  }

  function parseVals(elt) {
    const raw = elt.getAttribute("hx-vals");
    if (!raw) return {};
    try {
      if (raw.startsWith("js:")) {
        return Function("return (" + raw.slice(3) + ")").call(elt) || {};
      }
      return JSON.parse(raw);
    } catch (_) {
      return {};
    }
  }

  function addFormData(fd, data) {
    for (const [key, value] of Object.entries(data || {})) {
      if (value !== undefined && value !== null) fd.set(key, value);
    }
  }

  function requestBody(elt, method) {
    if (method === "GET") return null;
    let fd;
    const include = elt.getAttribute("hx-include");
    if (elt.tagName === "FORM") {
      fd = new FormData(elt);
    } else if (include === "this") {
      fd = new FormData();
      if (elt.name) fd.append(elt.name, elt.value || "");
    } else {
      const form = elt.closest("form");
      fd = form ? new FormData(form) : new FormData();
      if (include) {
        document.querySelectorAll(include).forEach(function (node) {
          if (node.tagName === "FORM") {
            for (const [k, v] of new FormData(node).entries()) fd.append(k, v);
          } else if (node.name) {
            fd.append(node.name, node.value || "");
          }
        });
      }
    }
    addFormData(fd, parseVals(elt));
    return fd;
  }

  function urlWithParams(url, elt, method) {
    if (method !== "GET") return url;
    const vals = parseVals(elt);
    const include = elt.getAttribute("hx-include");
    const params = new URLSearchParams();
    addFormData(params, vals);
    if (include) {
      document.querySelectorAll(include).forEach(function (node) {
        if (node.tagName === "FORM") {
          for (const [k, v] of new FormData(node).entries()) params.append(k, v);
        } else if (node.name) {
          params.append(node.name, node.value || "");
        }
      });
    }
    const qs = params.toString();
    if (!qs) return url;
    return url + (url.includes("?") ? "&" : "?") + qs;
  }

  function runAfter(elt, xhr) {
    const code = elt.getAttribute("hx-on::after-request");
    if (!code) return;
    try {
      Function("event", "xhr", code).call(elt, { target: elt, detail: { xhr } }, xhr);
    } catch (err) {
      console.error(err);
    }
  }

  function applyOob(fragment) {
    fragment.querySelectorAll("[hx-swap-oob]").forEach(function (node) {
      const id = node.id;
      if (!id) return;
      const dest = document.getElementById(id);
      if (!dest) return;
      const mode = node.getAttribute("hx-swap-oob") || "true";
      if (mode === "beforeend") dest.insertAdjacentHTML("beforeend", node.innerHTML);
      else if (mode === "afterbegin") dest.insertAdjacentHTML("afterbegin", node.innerHTML);
      else dest.replaceWith(node);
      node.remove();
    });
  }

  function swap(target, html, mode) {
    if (!target || mode === "none") return;
    const cleanMode = (mode || "innerHTML").split(/\s+/)[0];
    const tpl = document.createElement("template");
    tpl.innerHTML = html;
    applyOob(tpl.content);
    html = tpl.innerHTML;
    if (cleanMode === "outerHTML") target.outerHTML = html;
    else if (cleanMode === "beforeend") target.insertAdjacentHTML("beforeend", html);
    else if (cleanMode === "afterbegin") target.insertAdjacentHTML("afterbegin", html);
    else if (cleanMode === "afterbegin") target.insertAdjacentHTML("afterbegin", html);
    else target.innerHTML = html;
    process(document.body);
  }

  async function ajax(method, url, opts) {
    opts = opts || {};
    const target = typeof opts.target === "string" ? document.querySelector(opts.target) : opts.target;
    const headers = { "HX-Request": "true", "HX-Current-URL": location.href };
    const response = await fetch(url, { method, headers });
    const html = await response.text();
    swap(target, html, opts.swap || "innerHTML");
    trigger(target || document.body, "htmx:afterRequest", { xhr: response });
    trigger(target || document.body, "htmx:afterSettle", { xhr: response });
    return response;
  }

  async function issue(elt, override) {
    const found = override || methodOf(elt);
    if (!found) return;
    const confirmed = elt.getAttribute("hx-confirm");
    if (confirmed && !window.confirm(confirmed)) return;
    const method = found.method;
    const url = urlWithParams(found.url, elt, method);
    const target = targetFor(elt);
    const swapMode = elt.getAttribute("hx-swap") || "innerHTML";
    const headers = { "HX-Request": "true", "HX-Current-URL": location.href };
    const init = { method, headers };
    const body = requestBody(elt, method);
    if (body) init.body = body;
    elt.classList.add("htmx-request");
    trigger(elt, "htmx:beforeRequest", {});
    try {
      const response = await fetch(url, init);
      const redirect = response.headers.get("HX-Redirect");
      if (redirect) {
        location.href = redirect;
        return;
      }
      const html = await response.text();
      swap(target, html, swapMode);
      const push = elt.getAttribute("hx-push-url");
      if (push) history.pushState({}, "", push === "true" ? found.url : push);
      runAfter(elt, response);
      trigger(elt, "htmx:afterRequest", { xhr: response });
      trigger(elt, "htmx:afterSettle", { xhr: response });
    } finally {
      elt.classList.remove("htmx-request");
    }
  }

  function bind(elt) {
    if (elt.__mcHtmxBound) return;
    const found = methodOf(elt);
    if (!found) return;
    elt.__mcHtmxBound = true;
    const trig = elt.getAttribute("hx-trigger") || "";
    if (trig.includes("load")) setTimeout(function () { issue(elt, found); }, 0);
    const every = trig.match(/every\s+(\d+)s/);
    if (every) setInterval(function () { issue(elt, found); }, Number(every[1]) * 1000);
    if (trig.includes("input")) {
      let timer;
      elt.addEventListener("input", function () {
        clearTimeout(timer);
        timer = setTimeout(function () { issue(elt, found); }, 300);
      });
    } else if (trig.includes("change from:input")) {
      elt.addEventListener("change", function (event) {
        if (event.target && event.target.matches("input,select,textarea")) issue(elt, found);
      });
    } else if (trig.includes("change")) {
      elt.addEventListener("change", function () { issue(elt, found); });
    } else if (elt.tagName === "FORM") {
      elt.addEventListener("submit", function (event) {
        event.preventDefault();
        issue(elt, found);
      });
    } else {
      elt.addEventListener("click", function (event) {
        event.preventDefault();
        issue(elt, found);
      });
    }
  }

  function process(root) {
    (root || document).querySelectorAll("[hx-get],[hx-post],[hx-patch],[hx-delete]").forEach(bind);
  }

  window.htmx = { ajax, process };
  document.addEventListener("DOMContentLoaded", function () { process(document.body); });
})();
